type lane=Ownership|Metadata
type package=Geometry_descriptor|Instance_descriptor|Primitive_descriptor|Motion_data|Class_metadata|Instance_value
type item={id:string;lane:lane;package:package;operation:string;tests:string list}
let contains s n=let l=String.length n in let rec f i=i+l<=String.length s&&(String.sub s i l=n||f(i+1))in f 0
let classify~kind id=let lane=if kind="method"then Ownership else Metadata in let package,operation,tests=if kind="typedef"then Instance_value,"Metal.Acceleration_structure packed instance records",["fixed layout static_assert";"round trip and reserved bits"]else if lane=Metadata then Class_metadata,"Metal.Acceleration_structure descriptor/capability types",["public type provenance"]else if contains id "MotionKeyframeData"then Motion_data,"Metal.Acceleration_structure.Motion_keyframe",["owned buffer/offset graph";"range validation"]else if contains id "IndirectInstance"||contains id "InstanceAcceleration"then Instance_descriptor,"Metal.Acceleration_structure.Instance_descriptor",["instance buffer/stride/count validation";"same-device retention"]else if contains id "PrimitiveAcceleration"then Primitive_descriptor,"Metal.Acceleration_structure.Primitive_descriptor",["geometry array ownership";"empty rejection"]else Geometry_descriptor,"Metal.Acceleration_structure.Geometry_descriptor",["native defaults";"buffer ranges/formats";"destroy order"]in{id;lane;package;operation;tests}
let validate items=let count f=List.length(List.filter f items)in if List.length items<>28||count(fun x->x.lane=Ownership)<>10||count(fun x->x.lane=Metadata)<>18||List.map(fun p->count(fun x->x.package=p))[Geometry_descriptor;Instance_descriptor;Primitive_descriptor;Motion_data;Class_metadata;Instance_value]<>[6;2;1;1;13;5]then failwith"AccelerationStructure28 handoff drift"
